// Corpo enviado pelo app Mara Imóveis (ver EnvioContratoWebhook em
// src/domain/services/index.ts): evento, contrato, locatario, imovel, pdf
// e, só no evento "contrato.assinatura", telefoneEnvio.
const body = $input.first().json.body ?? $input.first().json;

const evento = body.evento;
const contrato = body.contrato ?? {};
const locatario = body.locatario ?? {};
const imovel = body.imovel ?? {};
const pdf = body.pdf ?? {};

// telefoneEnvio (escolhido no modal de assinatura) tem prioridade sobre o
// telefone cadastrado do inquilino — só dígitos, com DDI.
const numeroBruto = body.telefoneEnvio || locatario.telefone || "";
const numero = String(numeroBruto).replace(/\D/g, "");

if (!numero) {
  throw new Error("Nenhum telefone informado para o envio do contrato.");
}
if (!pdf.base64) {
  throw new Error("O corpo recebido não trouxe o PDF em base64.");
}

const legenda =
  evento === "contrato.assinatura"
    ? `Olá, ${locatario.nome}! Segue o contrato ${contrato.numero} referente ao imóvel "${imovel.titulo}" para assinatura. Após assinar, é só responder esta mensagem com o documento assinado.`
    : `Olá, ${locatario.nome}! Segue o contrato ${contrato.numero} referente ao imóvel "${imovel.titulo}".`;

return [
  {
    json: {
      evento,
      contratoId: contrato.id,
      numero,
      legenda,
      nomeArquivo: pdf.nomeArquivo || `contrato-${contrato.numero}.pdf`,
      base64: pdf.base64,
    },
  },
];
